using System;
using System.IO;
using System.Linq;
using RDR2ModHolster.Safety;
class Program {
 static int passed; static string baseDir;
 static void Main(){ baseDir=Path.Combine(Path.GetTempPath(),"SafetyTests-"+Guid.NewGuid()); Directory.CreateDirectory(baseDir);
 try { Run("70-file hash roundtrip and empty directory", RoundTrip); Run("collision preflight leaves all sources untouched", Collision); Run("repeated holster preserves backup", RepeatedHolster); Run("unknown DLL untouched", Unknown); Run("protected .egstore and forged protected candidate refused", Protected); Run("tampered traversal manifest rejected", Tampered); Run("symlink tree refused", Symlink); Run("extra backup stops purge", PurgeExtra); Run("legacy safe restore and conflict preservation", Legacy); Run("Documents modconfig restore", Documents); Run("restore resumes simulated partial transfer", PartialResume); Run("absent Documents root is accepted", AbsentDocuments); Run("nested link does not orphan a session", LinkNoOrphan); Run("partial source deletion resumes from backup", PartialSourceDeletion); Run("partial backup deletion resumes", PartialBackupDeletion); Run("precommit interruption with intact source is recoverable", IntactSourceRecovery); Run("identical Holstered collision refuses", IdenticalCollision); Run("legacy completion permits a new holster", LegacyThenHolster); Run("empty legacy Documents is ignored", EmptyLegacyDocuments); Run("legacy .egstore restores only to missing target", LegacyEgstore); Run("legacy steam executable is refused", LegacySteamExe); Run("purging sessions refuse restore and may resume purge", Purging); Run("Windows alias manifest names are rejected", WindowsAliases); Run("second interruption during holster undo remains resumable", UndoReinterrupted); V32.All(Run, baseDir); Console.WriteLine("PASS "+passed+" tests"); } finally { try{Directory.Delete(baseDir,true);}catch{} }
 }
 static void Run(string n, Action a){ if(OperatingSystem.IsWindows() && (a.Method.Name==nameof(Symlink)||a.Method.Name==nameof(LinkNoOrphan))) { Console.WriteLine("SKIP "+n+": Linux-only fixture; Windows junctions are covered by NativeTests"); return; } try { a(); passed++; Console.WriteLine("OK  "+n); } catch(Exception x){ Console.Error.WriteLine("FAIL "+n+": "+x); Environment.Exit(1); } }
 static string Fix(string n){ string p=Path.Combine(baseDir,n); Directory.CreateDirectory(p); Directory.CreateDirectory(Path.Combine(p,"game")); Directory.CreateDirectory(Path.Combine(p,"docs")); File.WriteAllText(Path.Combine(p,"game","RDR2.exe"),"synthetic"); return p; }
 static SafetyEngine E(string f){return new SafetyEngine(Path.Combine(f,"game"),Path.Combine(f,"docs"),null);}
 static Candidate C(SafetyEngine e,string name){var x=e.Scan().Items.FirstOrDefault(z=>z.Name==name); if(x==null)throw new Exception("candidate missing "+name);return x;}
 static void Yes(OperationResult r){if(!r.Success)throw new Exception(r.Message);}
 static void RoundTrip(){var f=Fix("round");var d=Path.Combine(f,"game","scripts");Directory.CreateDirectory(Path.Combine(d,"empty")); for(int i=0;i<70;i++)File.WriteAllText(Path.Combine(d,"f"+i+".asi"),new string((char)('a'+i%20),i+1)); var e=E(f);var hash=HashDir(d);var h=e.Holster(ModGroup.Mods,new[]{C(e,"scripts")});Yes(h); if(Directory.Exists(d))throw new Exception("source remains");Yes(e.Restore(h.SessionId));if(HashDir(d)!=hash||!Directory.Exists(Path.Combine(d,"empty")))throw new Exception("roundtrip mismatch"); }
 static void Collision(){var f=Fix("collision");File.WriteAllText(Path.Combine(f,"game","a.asi"),"a");File.WriteAllText(Path.Combine(f,"game","b.asi"),"b");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"a.asi"),C(e,"b.asi")});Yes(h);File.WriteAllText(Path.Combine(f,"game","b.asi"),"new");var r=e.Restore(h.SessionId);if(r.Success||File.Exists(Path.Combine(f,"game","a.asi"))||File.ReadAllText(Path.Combine(f,"game","b.asi"))!="new")throw new Exception("collision changed a destination before detecting b");if(!File.Exists(Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"Game","a.asi")))throw new Exception("collision discarded backup"); }
 static void RepeatedHolster(){var f=Fix("repeat");File.WriteAllText(Path.Combine(f,"game","a.asi"),"a");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"a.asi")});Yes(h);File.WriteAllText(Path.Combine(f,"game","b.asi"),"b");var r=e.Holster(ModGroup.Mods,new[]{C(e,"b.asi")});if(r.Success||!File.Exists(Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"Game","a.asi"))||!File.Exists(Path.Combine(f,"game","b.asi")))throw new Exception("repeated holster modified files"); }
 static void Unknown(){var f=Fix("unknown");File.WriteAllText(Path.Combine(f,"game","future_loader.dll"),"future");File.WriteAllText(Path.Combine(f,"game","x.asi"),"mod");var e=E(f); if(C(e,"future_loader.dll").Recommended)throw new Exception("unknown dll recommended");Yes(e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")}));if(!File.Exists(Path.Combine(f,"game","future_loader.dll")))throw new Exception("future dll moved");}
 static void Protected(){var f=Fix("protected");Directory.CreateDirectory(Path.Combine(f,"game",".egstore"));File.WriteAllText(Path.Combine(f,"game",".egstore","manifest"),"x");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");var e=E(f);var p=C(e,".egstore");if(!p.Protected)throw new Exception("not protected");var forged=new Candidate {Name=".egstore",FullPath=p.FullPath,IsDirectory=true,Group=ModGroup.Mods};var r=e.Holster(ModGroup.Mods,new[]{forged});if(r.Success||!Directory.Exists(p.FullPath))throw new Exception("forged protected moved");}
 static void Tampered(){var f=Fix("tamper");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")});Yes(h);var p=Path.Combine(h.SessionId==null?"":Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId),"manifest.xml");var s=File.ReadAllText(p).Replace("name=\"x.asi\"","name=\"..\\evil\"");File.WriteAllText(p,s);var r=e.Restore(h.SessionId);if(r.Success)throw new Exception("tampered manifest accepted");}
 static void Symlink(){if(OperatingSystem.IsWindows())return;var f=Fix("link");var target=Path.Combine(f,"target");Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(target,"z"),"z");Directory.CreateSymbolicLink(Path.Combine(f,"game","scripts"),target);var e=E(f);try{e.Scan();throw new Exception("link scan passed");}catch(IOException){} }
 static void PurgeExtra(){var f=Fix("purge");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")});Yes(h);File.WriteAllText(Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"Game","extra"),"bad");var r=e.Purge(h.SessionId);if(r.Success)throw new Exception("purge accepted extra");}
 static void Legacy(){var f=Fix("legacy");var l=Path.Combine(f,"game","_RDR2_Mods_Disabled");Directory.CreateDirectory(l);File.WriteAllText(Path.Combine(l,"x.asi"),"x");var e=E(f);Yes(e.RestoreLegacy(ModGroup.Mods));if(!File.Exists(Path.Combine(f,"game","x.asi")))throw new Exception("legacy not restored");var g=Fix("legacycollision");var ll=Path.Combine(g,"game","_RDR2_Mods_Disabled");Directory.CreateDirectory(ll);File.WriteAllText(Path.Combine(ll,"x.asi"),"old");File.WriteAllText(Path.Combine(g,"game","x.asi"),"new");var r=E(g).RestoreLegacy(ModGroup.Mods);if(r.Success||!File.Exists(Path.Combine(ll,"x.asi")))throw new Exception("legacy collision destructive");}
 static void Documents(){var f=Fix("docs");var m=Path.Combine(f,"docs","modconfig");Directory.CreateDirectory(m);File.WriteAllText(Path.Combine(m,"a"),"x");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"Documents/modconfig")});Yes(h);if(Directory.Exists(m))throw new Exception("documents remains");Yes(e.Restore(h.SessionId));if(!File.Exists(Path.Combine(m,"a")))throw new Exception("documents absent after restore");}
 static void PartialResume(){var f=Fix("partial");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")});Yes(h);var session=Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId);File.Copy(Path.Combine(session,"Game","x.asi"),Path.Combine(f,"game","x.asi"));var mp=Path.Combine(session,"manifest.xml");File.WriteAllText(mp,File.ReadAllText(mp).Replace("state=\"Holstered\"","state=\"Holstering\"").Replace("state=\"BackedUp\"","state=\"RemovingSource\""));Yes(e.Restore(h.SessionId));if(!File.Exists(Path.Combine(f,"game","x.asi"))||File.Exists(Path.Combine(session,"Game","x.asi")))throw new Exception("partial transfer was not deterministically resolved");}
 static void AbsentDocuments(){var f=Fix("absentdocs");Directory.Delete(Path.Combine(f,"docs"));var e=E(f);if(e.Scan().Items.Any(x=>x.Name=="Documents/modconfig"))throw new Exception("missing Documents scanned");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");Yes(e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")}));}
 static void LinkNoOrphan(){if(OperatingSystem.IsWindows())return;var f=Fix("linkorphan");var t=Path.Combine(f,"target");Directory.CreateDirectory(t);File.WriteAllText(Path.Combine(t,"x"),"x");var link=Path.Combine(f,"game","scripts");Directory.CreateSymbolicLink(link,t);var e=E(f);var r=e.Holster(ModGroup.Mods,new[]{new Candidate{Name="scripts",FullPath=link,IsDirectory=true,Group=ModGroup.Mods}});if(r.Success)throw new Exception("link holstered");var store=Path.Combine(f,"game","_RDR2_ModHolster");if(Directory.GetDirectories(store).Any(x=>Path.GetFileName(x)!="logs"&&Path.GetFileName(x)!=".staging"))throw new Exception("orphan session");Directory.Delete(link);Directory.CreateDirectory(link);File.WriteAllText(Path.Combine(link,"ok"),"x");Yes(e.Holster(ModGroup.Mods,new[]{C(e,"scripts")}));}
 static void PartialSourceDeletion(){var f=Fix("partialsource");var d=Path.Combine(f,"game","scripts");Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"a"),"a");File.WriteAllText(Path.Combine(d,"b"),"b");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"scripts")});Yes(h);Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"a"),"a");var p=Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"manifest.xml");var s=File.ReadAllText(p).Replace("state=\"Holstered\"","state=\"Holstering\"").Replace("state=\"BackedUp\"","state=\"RemovingSource\"");File.WriteAllText(p,s);Yes(e.Restore(h.SessionId));if(!File.Exists(Path.Combine(d,"a"))||!File.Exists(Path.Combine(d,"b")))throw new Exception("missing partial recovery content");}
 static void PartialBackupDeletion(){var f=Fix("partialbackup");var d=Path.Combine(f,"game","scripts");Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"a"),"a");File.WriteAllText(Path.Combine(d,"b"),"b");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"scripts")});Yes(h);var b=Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"Game","scripts");Directory.CreateDirectory(d);File.Copy(Path.Combine(b,"a"),Path.Combine(d,"a"));File.Copy(Path.Combine(b,"b"),Path.Combine(d,"b"));File.Delete(Path.Combine(b,"a"));var p=Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"manifest.xml");File.WriteAllText(p,File.ReadAllText(p).Replace("state=\"Holstered\"","state=\"Restoring\"").Replace("state=\"BackedUp\"","state=\"Restoring\""));Yes(e.Restore(h.SessionId));if(Directory.Exists(b))throw new Exception("partial backup not completed");}
 static void IntactSourceRecovery(){var f=Fix("intactsource");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")});Yes(h);var b=Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"Game","x.asi");File.Copy(b,Path.Combine(f,"game","x.asi"));File.Delete(b);var p=Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"manifest.xml");File.WriteAllText(p,File.ReadAllText(p).Replace("state=\"Holstered\"","state=\"Holstering\"").Replace("state=\"BackedUp\"","state=\"Copying\""));Yes(e.Restore(h.SessionId));if(!File.Exists(Path.Combine(f,"game","x.asi")))throw new Exception("intact source lost");}
 static void IdenticalCollision(){var f=Fix("samecollision");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")});Yes(h);File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");if(e.Restore(h.SessionId).Success)throw new Exception("identical collision accepted");}
 static void LegacyThenHolster(){var f=Fix("legacythen");var l=Path.Combine(f,"game","_RDR2_Mods_Disabled");Directory.CreateDirectory(l);File.WriteAllText(Path.Combine(l,"x.asi"),"x");var e=E(f);Yes(e.RestoreLegacy(ModGroup.Mods));if(e.HasLegacy(ModGroup.Mods))throw new Exception("empty legacy root remains pending");Yes(e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")}));}
 static void EmptyLegacyDocuments(){var f=Fix("emptyolddocs");Directory.CreateDirectory(Path.Combine(f,"game","_RDR2_Mods_Disabled","Documents"));var e=E(f);if(e.HasLegacy(ModGroup.Mods))throw new Exception("empty old Documents pending");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");Yes(e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")}));}
 static void LegacyEgstore(){var f=Fix("legacystore");var old=Path.Combine(f,"game","_RDR2_Mods_Disabled",".egstore");Directory.CreateDirectory(old);File.WriteAllText(Path.Combine(old,"m"),"x");var e=E(f);Yes(e.RestoreLegacy(ModGroup.Mods));if(!File.Exists(Path.Combine(f,"game",".egstore","m")))throw new Exception("legacy store missing");}
 static void LegacySteamExe(){var f=Fix("legacysteam");var old=Path.Combine(f,"game","_RDR2_Mods_Disabled");Directory.CreateDirectory(old);File.WriteAllText(Path.Combine(old,"steam.exe"),"x");var r=E(f).RestoreLegacy(ModGroup.Mods);if(r.Success||!File.Exists(Path.Combine(old,"steam.exe")))throw new Exception("legacy executable accepted");}
 static void Purging(){var f=Fix("purging");File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")});Yes(h);var p=Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"manifest.xml");File.WriteAllText(p,File.ReadAllText(p).Replace("state=\"Holstered\"","state=\"Purging\""));if(e.Restore(h.SessionId).Success)throw new Exception("purging restored");File.Delete(Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"Game","x.asi"));Yes(e.Purge(h.SessionId));if(e.GetSessions(ModGroup.Mods).Any(x=>x.Id==h.SessionId))throw new Exception("purged session active");}
 static void WindowsAliases(){foreach(var bad in new[]{"CON.asi","x.asi.","x.asi ","COM1.txt","a:b"}){var f=Fix("alias"+bad.GetHashCode());File.WriteAllText(Path.Combine(f,"game","x.asi"),"x");var e=E(f);var h=e.Holster(ModGroup.Mods,new[]{C(e,"x.asi")});Yes(h);var p=Path.Combine(f,"game","_RDR2_ModHolster",h.SessionId,"manifest.xml");File.WriteAllText(p,File.ReadAllText(p).Replace("name=\"x.asi\"","name=\""+bad+"\""));if(e.Restore(h.SessionId).Success)throw new Exception("alias accepted "+bad);}}

 static void UndoReinterrupted(){
  var f=Fix("undo-reinterrupted"); var game=Path.Combine(f,"game");
  File.WriteAllText(Path.Combine(game,"a.asi"),"a"); File.WriteAllText(Path.Combine(game,"b.asi"),"b");
  var e=E(f); var h=e.Holster(ModGroup.Mods,new[]{C(e,"a.asi"),C(e,"b.asi")}); Yes(h);
  var folder=Path.Combine(game,"_RDR2_ModHolster",h.SessionId); var mp=Path.Combine(folder,"manifest.xml");
  var doc=System.Xml.Linq.XDocument.Load(mp); doc.Root.SetAttributeValue("state","Holstering");
  foreach(var item in doc.Root.Elements("Item")){
   string n=(string)item.Attribute("name"); File.Move(Path.Combine(folder,"Game",n),Path.Combine(game,n));
   item.SetAttributeValue("state",n=="a.asi"?"Copying":"Source");
  }
  doc.Save(mp);
  SafetyEngine.FaultInjector = point=>{if(point=="AfterRestoreJournal")throw new IOException("Synthetic interrupted restore journal");};
  OperationResult first; try{first=e.Restore(h.SessionId);}finally{SafetyEngine.FaultInjector=null;}
  if(first.Success)throw new Exception("fault did not fire");
  Yes(e.Restore(h.SessionId));
  if(File.ReadAllText(Path.Combine(game,"a.asi"))!="a"||File.ReadAllText(Path.Combine(game,"b.asi"))!="b")throw new Exception("undo retry failed to preserve originals");
 }
 static string HashDir(string p){using var sha=System.Security.Cryptography.SHA256.Create();var b=System.Text.Encoding.UTF8.GetBytes(string.Join("|",Directory.GetFiles(p,"*",SearchOption.AllDirectories).OrderBy(x=>x).Select(x=>x+":"+File.ReadAllText(x))));return Convert.ToHexString(sha.ComputeHash(b));}
}
